method smallest_change(arr: seq<int>) returns (changes: int)
    requires |arr| > 0 // Array must not be empty
    ensures changes >= 0 // Number of changes cannot be negative
    ensures changes == CountChanges(arr) // Postcondition to ensure 'changes' is calculated correctly

// Helper function to count the minimum changes needed to make the array palindromic
function CountChanges(arr: seq<int>): int
    requires |arr| > 0
    reads arr
    ensures 0 <= CountChanges(arr) <= |arr| / 2 // Changes should be non-negative and cannot exceed half the length of the array
{
    var n := |arr|;
    var count := 0;
    var i := 0;
    while i < n / 2
        invariant 0 <= i <= n / 2 // i is within valid range
        invariant count >= 0 // Count of changes is non-negative
    {
        if arr[i] != arr[n - 1 - i] {
            count := count + 1; // Increment count if elements are not equal
        }
        i := i + 1; // Move to the next pair
    }
    return count;
}
```

